SELECT 'kioscos'::text AS entity, t.id::uuid AS id, NULL::uuid AS kiosco_id, NULL::text AS parent_relation, NULL::uuid AS parent_id, NULL::text AS secondary_parent_relation, NULL::uuid AS secondary_parent_id, NULL::text AS tertiary_parent_relation, NULL::uuid AS tertiary_parent_id, NULL::text AS record_state, NULL::timestamptz AS closed_at, NULL::boolean AS es_superadmin, NULL::boolean AS activo, NULL::text AS rol, (CASE WHEN t.nombre = 'Bazar y Hogar Prisma' AND (SELECT count(*) FROM public.categorias c WHERE c.kiosco_id = t.id) = 9 AND (SELECT count(DISTINCT c.nombre) FROM public.categorias c WHERE c.kiosco_id = t.id AND c.nombre IN ('Sets y Promociones', 'Cocina y Vajilla', 'Utensilios y Cocción', 'Repostería y Moldes', 'Termos, Mates y Bebidas', 'Conservación y Herméticos', 'Organización y Limpieza', 'Decoración y Regalería', 'Baño y Textiles')) = 9 AND NOT EXISTS (SELECT 1 FROM public.categorias c WHERE c.kiosco_id = t.id AND c.nombre NOT IN ('Sets y Promociones', 'Cocina y Vajilla', 'Utensilios y Cocción', 'Repostería y Moldes', 'Termos, Mates y Bebidas', 'Conservación y Herméticos', 'Organización y Limpieza', 'Decoración y Regalería', 'Baño y Textiles')) AND (SELECT count(*) FROM public.productos p WHERE p.kiosco_id = t.id) = 48 AND (SELECT count(DISTINCT p.codigo_barras) FROM public.productos p WHERE p.kiosco_id = t.id AND p.codigo_barras IN ('7792001001014', '7792001001021', '7792001001038')) = 3 THEN 'SEED_BAZAR_PRISMA_V1' WHEN t.nombre = 'Kiosco y Almacén Don Pedro' AND (SELECT count(*) FROM public.categorias c WHERE c.kiosco_id = t.id) = 9 AND (SELECT count(DISTINCT c.nombre) FROM public.categorias c WHERE c.kiosco_id = t.id AND c.nombre IN ('Combos y Promociones', 'Golosinas y Alfajores', 'Galletitas y Snacks', 'Bebidas sin Alcohol', 'Cervezas y Bebidas Alcohólicas', 'Almacén Básico', 'Fiambrería y Quesos', 'Congelados', 'Cigarrillos, Pilas y Varios')) = 9 AND NOT EXISTS (SELECT 1 FROM public.categorias c WHERE c.kiosco_id = t.id AND c.nombre NOT IN ('Combos y Promociones', 'Golosinas y Alfajores', 'Galletitas y Snacks', 'Bebidas sin Alcohol', 'Cervezas y Bebidas Alcohólicas', 'Almacén Básico', 'Fiambrería y Quesos', 'Congelados', 'Cigarrillos, Pilas y Varios')) AND (SELECT count(*) FROM public.productos p WHERE p.kiosco_id = t.id) = 97 AND (SELECT count(DISTINCT p.codigo_barras) FROM public.productos p WHERE p.kiosco_id = t.id AND p.codigo_barras IN ('7790580200012', '7790580200029', '7790580200036')) = 3 THEN 'SEED_DON_PEDRO_V1' WHEN t.nombre = 'Librería y Papelera Sol' AND (SELECT count(*) FROM public.categorias c WHERE c.kiosco_id = t.id) = 9 AND (SELECT count(DISTINCT c.nombre) FROM public.categorias c WHERE c.kiosco_id = t.id AND c.nombre IN ('Combos y Promociones', 'Cuadernos y Carpetas', 'Útiles Escolares', 'Escritura', 'Papelería y Hojas', 'Arte y Manualidades', 'Tecnología y Accesorios', 'Cartuchería e Impresión', 'Mochilas y Accesorios')) = 9 AND NOT EXISTS (SELECT 1 FROM public.categorias c WHERE c.kiosco_id = t.id AND c.nombre NOT IN ('Combos y Promociones', 'Cuadernos y Carpetas', 'Útiles Escolares', 'Escritura', 'Papelería y Hojas', 'Arte y Manualidades', 'Tecnología y Accesorios', 'Cartuchería e Impresión', 'Mochilas y Accesorios')) AND (SELECT count(*) FROM public.productos p WHERE p.kiosco_id = t.id) = 99 AND (SELECT count(DISTINCT p.codigo_barras) FROM public.productos p WHERE p.kiosco_id = t.id AND p.codigo_barras IN ('7790001000010', '7790001000027', '7790001000034')) = 3 THEN 'SEED_LIBRERIA_SOL_V1' WHEN t.nombre = 'Maxikiosco & Heladería Marchelo' AND (SELECT count(*) FROM public.categorias c WHERE c.kiosco_id = t.id) = 8 AND (SELECT count(DISTINCT c.nombre) FROM public.categorias c WHERE c.kiosco_id = t.id AND c.nombre IN ('Combos y Promociones', 'Helados Marchelo', 'Panizados La Reina', 'Gaseosas y Bebidas', 'Almacén y Comestibles', 'Fiambrería y Quesos', 'Golosinas y Snacks', 'Cigarrillos y Varios')) = 8 AND NOT EXISTS (SELECT 1 FROM public.categorias c WHERE c.kiosco_id = t.id AND c.nombr